package com.cinenest.payments.internal;

import java.time.*;
import java.sql.*;
import java.util.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

/** Prepared adapter only: feature disabled by default; schema requires separate approval. */
@Repository
final class JdbcBankInstructionPublicationRepository implements BankInstructionPublicationRepository {
    private final JdbcClient jdbc;
    JdbcBankInstructionPublicationRepository(JdbcClient jdbc){this.jdbc=jdbc;}
    public Instant now(){return jdbc.sql("SELECT clock_timestamp()").query(OffsetDateTime.class).single().toInstant();}
    private static UUID id(ResultSet r,String key)throws SQLException{return r.getObject(key,UUID.class);}
    private static Proposal proposal(ResultSet r)throws SQLException{return new Proposal(id(r,"proposal_id"),id(r,"venue_id"),id(r,"proposer_id"),new BankInstructionPublicationPolicy.Draft(r.getString("instruction_version"),id(r,"reference_id"),id(r,"reference_version"),r.getString("content_sha256"),r.getTimestamp("effective_from").toInstant(),r.getTimestamp("effective_until").toInstant(),r.getString("snapshot_sha256")));}
    private static Event event(ResultSet r)throws SQLException{return new Event(id(r,"command_id"),id(r,"actor_id"),id(r,"command_key"),id(r,"venue_id"),id(r,"proposal_id"),r.getString("action"),r.getString("payload_sha256"),r.getLong("expected_revision"),r.getLong("revision"),r.getString("state"),id(r,"reviewer_id"),id(r,"published_revision_id"),r.getTimestamp("occurred_at").toInstant(),id(r,"correlation_id"),id(r,"audit_id"));}
    public Optional<Snapshot> find(UUID venue,UUID target,boolean lock){return jdbc.sql("SELECT p.*,c.* FROM cinenest_payments.bank_instruction_proposal p JOIN LATERAL (SELECT * FROM cinenest_payments.bank_instruction_publication_command c WHERE c.proposal_id=p.proposal_id ORDER BY c.revision DESC LIMIT 1) c ON true WHERE p.venue_id=:v AND p.proposal_id=:p"+(lock?" FOR UPDATE OF p":"")).param("v",venue).param("p",target).query((r,n)->new Snapshot(proposal(r),event(r))).optional();}
    public Optional<Event> receipt(UUID actor,UUID key){return jdbc.sql("SELECT * FROM cinenest_payments.bank_instruction_publication_command WHERE actor_id=:a AND command_key=:k").param("a",actor).param("k",key).query((r,n)->event(r)).optional();}
    public void insertProposal(Proposal p){var d=p.draft();jdbc.sql("INSERT INTO cinenest_payments.bank_instruction_proposal(proposal_id,venue_id,proposer_id,instruction_version,reference_id,reference_version,content_sha256,effective_from,effective_until,snapshot_sha256) VALUES(:p,:v,:a,:iv,:r,:rv,:h,:f,:u,:s)").param("p",p.id()).param("v",p.venue()).param("a",p.proposer()).param("iv",d.version()).param("r",d.reference()).param("rv",d.referenceVersion()).param("h",d.digest()).param("f",d.from().atOffset(ZoneOffset.UTC)).param("u",d.until().atOffset(ZoneOffset.UTC)).param("s",d.hash()).update();}
    public void insertEvent(Event e){jdbc.sql("INSERT INTO cinenest_payments.bank_instruction_publication_command(command_id,actor_id,command_key,venue_id,proposal_id,action,payload_sha256,expected_revision,revision,state,reviewer_id,published_revision_id,occurred_at,correlation_id,audit_id) VALUES(:id,:a,:k,:v,:p,:action,:h,:er,:r,:s,:reviewer,:published,:at,:c,:audit)").param("id",e.id()).param("a",e.actor()).param("k",e.key()).param("v",e.venue()).param("p",e.proposal()).param("action",e.action()).param("h",e.payloadHash()).param("er",e.expectedRevision()).param("r",e.revision()).param("s",e.state()).param("reviewer",e.reviewer(),Types.OTHER).param("published",e.published(),Types.OTHER).param("at",e.at().atOffset(ZoneOffset.UTC)).param("c",e.correlation()).param("audit",e.audit()).update();}
    public void audit(Event e){insertAudit(e.audit(),e.id(),e.actor(),e.venue(),e.proposal(),e.action(),"ALLOW","STAGING_COMMAND",e.at(),e.correlation());}
    public void readAudit(UUID actor,Snapshot s,UUID correlation){insertAudit(UUID.randomUUID(),null,actor,s.proposal().venue(),s.proposal().id(),"READ","ALLOW","SCOPED_READ",now(),correlation);}
    public void denied(UUID actor,UUID venue,String action,String reason,UUID correlation){insertAudit(UUID.randomUUID(),null,actor,venue,null,action,"DENY",reason,now(),correlation);}
    private void insertAudit(UUID id,UUID command,UUID actor,UUID venue,UUID proposal,String action,String outcome,String reason,Instant at,UUID correlation){jdbc.sql("INSERT INTO cinenest_payments.bank_instruction_publication_audit(audit_id,command_id,actor_id,venue_id,proposal_id,action,outcome,reason_code,occurred_at,correlation_id) VALUES(:id,:cmd,:a,:v,:p,:action,:o,:r,:at,:c)").param("id",id).param("cmd",command,Types.OTHER).param("a",actor,Types.OTHER).param("v",venue,Types.OTHER).param("p",proposal,Types.OTHER).param("action",action).param("o",outcome).param("r",reason).param("at",at.atOffset(ZoneOffset.UTC)).param("c",correlation).update();}
    public void publish(Proposal p,Event e){var d=p.draft();jdbc.sql("INSERT INTO cinenest_payments.bank_instruction_revision(instruction_revision_id,venue_id,instruction_version,mode,reference_id,reference_version,content_sha256,effective_from,effective_until,proposer_id,approver_id,approval_reference,approval_sha256,approved_at) VALUES(:id,:v,:version,'STAGING_ONLY',:ref,:rv,:h,:f,:u,:proposer,:publisher,:approval,:sha,:at)").param("id",e.published()).param("v",p.venue()).param("version",d.version()).param("ref",d.reference()).param("rv",d.referenceVersion()).param("h",d.digest()).param("f",d.from().atOffset(ZoneOffset.UTC)).param("u",d.until().atOffset(ZoneOffset.UTC)).param("proposer",p.proposer()).param("publisher",e.actor()).param("approval",e.id()).param("sha",d.hash()).param("at",e.at().atOffset(ZoneOffset.UTC)).update();}
}
